import React, { useState, useEffect, useContext } from "react";
import { AuthContext } from "../context/authContext";
import api from "../services/api";
import { API_ENDPOINTS } from "../services/apiEndpoints";
import WallForm from "../components/walls/wallForm";
import TweetForm from "../components/walls/tweetForm";
import TweetList from "../components/walls/tweetList";
import { useNavigate } from "react-router-dom";

const Dashboard = () => {
    const { user, logout } = useContext(AuthContext);
    const [walls, setWalls] = useState([]);
    const [selectedWall, setSelectedWall] = useState(null);
    const [sharableLink, setSharableLink] = useState("");
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const navigate = useNavigate();

    useEffect(() => {
        const fetchWalls = async () => {
            try {
                const response = await api.get(API_ENDPOINTS.GET_ALL_WALLS);
                setWalls(response.data);
                setLoading(false);
            } catch (err) {
                setError("Failed to load walls");
                setLoading(false);
            }
        };

        fetchWalls();
    }, []);

    const handleLogout = async () => {
        try {
            await logout();
            window.location.href = "/login";
        } catch (err) {
            console.error("Logout failed:", err);
        }
    };

    const handleGenerateSharableLink = async (wallId) => {
        try {
            const response = await api.get(
                API_ENDPOINTS.GENERATE_SHARABLE_LINK
            );
            setSharableLink(response.data.link);
        } catch (err) {
            setError("Failed to generate sharable link");
        }
    };

    const handleWallCreated = (newWall) => {
        setWalls([...walls, newWall]);
    };

    const handleTweetAdded = (newTweet) => {
        setSelectedWall({
            ...selectedWall,
            tweet: [...(selectedWall.tweet || []), newTweet],
        });
    };

    const handleDeleteWall = async (wallId) => {
        try {
            await api.delete(API_ENDPOINTS.DELETE_WALL(wallId));
            setWalls(walls.filter((wall) => wall.id !== wallId));
            if (selectedWall?.id === wallId) setSelectedWall(null);
        } catch (err) {
            setError("Failed to delete wall");
        }
    };

    if (!user)
        return (
            <div className="text-center p-6">
                Please log in to access the dashboard.
            </div>
        );
    if (loading) return <div className="text-center p-6">Loading...</div>;
    if (error)
        return <div className="text-center p-6 text-red-500">{error}</div>;

    return (
        <div className="p-6">
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold">Dashboard</h2>
                <div className="space-x-4">
                    <button
                        onClick={handleLogout}
                        className="bg-green-500 text-white px-4 py-2 rounded hover:bg-red-600"
                    >
                        Create Wall
                    </button>
                    <button
                        onClick={() => navigate("/profile")}
                        className="bg-green-500 text-white px-4 py-2 rounded hover:bg-green-600"
                    >
                        Profile
                    </button>
                    <button
                        onClick={handleLogout}
                        className="bg-red-500 text-white px-4 py-2 rounded hover:bg-red-600"
                    >
                        Logout
                    </button>
                </div>
            </div>
            <WallForm onWallCreated={handleWallCreated} />
            <div className="mt-6">
                <h3 className="text-xl font-semibold mb-4">Your Walls</h3>
                {walls.length === 0 ? (
                    <p>No walls created yet.</p>
                ) : (
                    <ul className="space-y-4">
                        {walls.map((wall) => (
                            <li
                                key={wall.id}
                                className="p-4 bg-gray-100 rounded-lg shadow"
                            >
                                <h4 className="text-lg font-medium">
                                    {wall.title}
                                </h4>
                                <p>{wall.description}</p>
                                <p>Public: {wall.is_public ? "Yes" : "No"}</p>
                                {wall.logo && <img src={wall.logo} />}
                                <div className="flex space-x-4 mt-2">
                                    <button
                                        onClick={() => setSelectedWall(wall)}
                                        className="text-blue-500 hover:underline"
                                    >
                                        Manage Tweets
                                    </button>
                                    <button
                                        onClick={() =>
                                            handleGenerateSharableLink(wall.id)
                                        }
                                        className="text-blue-500 hover:underline"
                                    >
                                        Get Sharable Link
                                    </button>
                                    <button
                                        onClick={() =>
                                            handleDeleteWall(wall.id)
                                        }
                                        className="text-red-500 hover:underline"
                                    >
                                        Delete
                                    </button>
                                </div>
                                {sharableLink && (
                                    <p className="mt-2">
                                        Sharable Link:{" "}
                                        <a
                                            href={sharableLink}
                                            className="text-blue-500 hover:underline"
                                        >
                                            {sharableLink}
                                        </a>
                                    </p>
                                )}
                            </li>
                        ))}
                    </ul>
                )}
            </div>
            {selectedWall && (
                <div className="mt-6">
                    <h3 className="text-xl font-semibold mb-4">
                        Manage Tweets for {selectedWall.title}
                    </h3>
                    <TweetForm
                        wallId={selectedWall.id}
                        onTweetAdded={handleTweetAdded}
                    />
                    <TweetList wallId={selectedWall.id} />
                </div>
            )}
        </div>
    );
};

export default Dashboard;
